/// <summary>
///     Extension of class <c>InventTransOrderPackingSlipDP</c>
///    The data provider class for the <c>InventTransferOrderPackingSlip</c> report.
/// </summary>
[ExtensionOf(classStr(InventTransOrderPackingSlipDP))]
final class AVAInventTransOrderPackingSlipDPCls_Extension
{
    public int clsAdditionalInfoNo;

}

Method.Source:
/// <summary>
/// This method inserts data into the <c>InventTransferOrderPackingSlipTmp</c> temporary table.
/// </summary>
/// <param name="_inventTransferJour">
/// The <c>InventTransferJour</c> table object.
/// </param>
/// <param name="_inventTransferJourLine">
/// The <c>InventTransferJourLine</c> table object.
/// </param>
public void avaInsertInventTransferOrderPackingSlipPro( InventTransferJour      _inventTransferJour, 
                                                        InventTransferJourLine  _inventTransferJourLine)
{
    InventTransferTable     locInventTransferTable;
    InventTransferLine      locInventTransferLine;
    InventLocation          locInventLocationFrom;
    InventLocation          locInventLocationTo;

    locInventTransferTable  = InventTransferTable::find(_inventTransferJour.TransferId);
    locInventTransferLine   = _inventTransferJourLine.inventTransferLine();
    locInventLocationFrom   = InventLocation::find(_inventTransferJour.InventLocationIdFrom);
    locInventLocationTo     = InventLocation::find(_inventTransferJour.InventLocationIdTo);

    clsAdditionalInfoNo++;

    inventTransferOrderPackingSlipProTmp.AVADetailRecId                     = _inventTransferJourLine.RecId;
    inventTransferOrderPackingSlipProTmp.AVAReportLineType                  = AVAReportLineType::Default;
    inventTransferOrderPackingSlipProTmp.AVAAdditionalInfoNo                = 1;
    inventTransferOrderPackingSlipProTmp.AVARefRecId                        =_inventTransferJourLine.RecId;
    inventTransferOrderPackingSlipProTmp.AVARefTableId                      =_inventTransferJourLine.TableId;
    inventTransferOrderPackingSlipProTmp.AVAFormat                          = AVAFormat::Default;
    inventTransferOrderPackingSlipProTmp.AVAKCS_SOCPickingReleaseIndicator  = locInventTransferLine.KCS_SOCPickingReleaseIndicator;
    inventTransferOrderPackingSlipProTmp.AVAItemSet                         = locInventTransferLine.AVAItemSet;
    inventTransferOrderPackingSlipProTmp.AVAItemSetExpanded                 = locInventTransferLine.AVAItemSetExpanded;
    inventTransferOrderPackingSlipProTmp.AVAItemSetComponent                = locInventTransferLine.AVAItemSetComponent;
    inventTransferOrderPackingSlipProTmp.AVAItemSetInventTransId            = locInventTransferLine.InventTransId;
    inventTransferOrderPackingSlipProTmp.AVAItemSetParent                   = locInventTransferLine.AVAItemSetParent;
    inventTransferOrderPackingSlipProTmp.AVAItemSetCompQtyPerSerie          = locInventTransferLine.AVAItemSetCompQtyPerSerie;
    inventTransferOrderPackingSlipProTmp.AVAItemSetSerie                    = locInventTransferLine.AVAItemSetSerie;
    inventTransferOrderPackingSlipProTmp.AVAProdSchedDate                   = locInventTransferLine.AVAProdSchedDate;
    /*
    next insertInventTransferOrderPackingSlipPro(   _inventTransferJour,
                                                    _inventTransferJourLine );
    */
}
